def resolve(path, cwd, links):
    # Validate cwd
    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd to remove trailing slash (except for root)
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with cwd if path is relative
    if path[0] != '/':
        current = cwd
    else:
        current = ''

    # Split path into components
    components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '/':
                # Already at root, stay at root
                pass
            else:
                # Remove last component
                if '/' in current:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                else:
                    current = '/'
            i += 1
            continue

        # Append component
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Get remaining components after current position
            remaining = components[i + 1:]

            # Parse target and combine with remaining
            if target[0] == '/':
                # Absolute target - start from root
                target_components = target.split('/')
            else:
                # Relative target - relative to the directory containing the link
                if '/' in candidate:
                    link_dir = candidate.rsplit('/', 1)[0]
                else:
                    link_dir = '/'
                target_components = (link_dir + '/' + target).split('/')

            # Combine target components with remaining components
            components = target_components + remaining

            # Reset current to empty (will be set based on whether target was absolute)
            if target[0] == '/':
                current = ''
            else:
                # Rewind - we need to restart from the link directory
                if '/' in candidate:
                    current = candidate.rsplit('/', 1)[0]
                else:
                    current = '/'
                components = target.split('/') + remaining

            i = 0
            continue

        # Not a symlink, just update current
        current = candidate
        i += 1

    # Normalize result
    if current == '':
        current = '/'
    elif current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

